// Стандарт С++20

#include <iostream>
#include <string>
#include <format>
#include <string_view>                                       // Подключение заголовочного файла для наложения взгляда на строку, также определения размера этой строки;
#include <cstddef>                                           // Подключение заголовочного файла, где определен типа size_t;

int main()
{
    constexpr std::string_view target{"жопа"};            // Класс string_view() накладывает взгляд на инициализированную константную строку, которая вычисляется на этапе компиляции. Целевая полная строка;
    constexpr std::string_view tail{"опа"};               // Класс string_view() накладывает взгляд на инициализированную константную строку, которая вычисляется на этапе компиляции. Хвост полной строки;
    constexpr std::string_view alphabet{"абвгдеёжзийклмнопрстуфхцчшщъыьэюя"}; // Класс string_view() накладывает взгляд на инициализированную константную строку, которая вычисляется на этапе компиляции. Строка символов русского алфавита, от которой по символу проверяются с первым символом полной строки;
    std::string word{"?опа"};                              // Инициализация объекта строки строковым литералом;

    for (std::size_t i{0}; word != target && i < alphabet.size(); ) // Определение цикла for. 1 - инициализация переменной-счетчика беззнакового типа. 2 - выражение сравнения. Если строка записанная в объект строки не равна константному объекту счетчик-переменная меньше значения размера объекта строки alphabet, результат будет true, если строки будут равны или счетчик-переменная равна или больше объекта строки alphabet - будет false, тем самым цикл for завершится;
    {
        const std::size_t start{i};                          // Инициализация защищенной переменной значением, представляющей далее в программе индекс байта символа строки;
        ++i;                                                 // Префиксное инкрементирование переменной. Представляющей далее в программе переменной для сдвига на следующий байт строки;

        for (; i < alphabet.size() && ((static_cast<unsigned char>(alphabet[i]) & 0xC0) == 0x80); ++i) {} // Определение внутреннего цикла for. 1 - инициализатор задан во внешнем цикле, 2 - выражение сравнения, проверяется выход за границу строки, затем производится явное приведение к беззнаковому типу unsigned char элемента строки и побитовая проверка маской, 3 - выражение итерации с увеличением на 1 с каждым циклом.
                                                                                                          // Кириллические символы в кодировке UTF-8 состоят из 2 байт: 1-й начинается с 11......, 2-й (хвост) начинается с 10......; проверка идет слева направо, цикл перешагивает 2-й байт и останавливается на следующем 1-м байте символа, ничего не выкидывая.
                                                                                                          // У всех символов от 2 до 4 байт первый байт начинается с 11......, а у остальных начинаются с 10........ Получается в этом цикле байты с 10....... просто пропускаются и в программе никак не обрабатываются только сдвигается счетчик цикла означающий сдвиг на следующий байт символа;

        std::cout << std::format("{}\n",word);
        word = std::format("{}{}", alphabet.substr(start, i - start), tail);                 // Метод substr(откуда, сколько) берем кусок начиная с индекса start длиной (i - start) байт (1 для латиницы, 2 для кириллицы, 4 для эмодзи) и формируем букву целиком, 2 аргумент прицепляет хвост строки к букве. Собранная строка присваивается объекту строки и сравнивается во внешнем цикле;
    }
    std::cout << std::format("Вывод слова {} по завершению цикла.\n", word);
}



